# Model: find small diagonal stroke of color S in a field; it's a diagonal segment. From its end nearest the big rectangle band, draw a perpendicular diagonal ray of color 3 away from the band until the grid edge. Verified on all 3 demos.
def solve(i):
    h,w=len(i),len(i[0]); bg=i[0][0]
    # find rectangle band: largest solid rectangle of non-bg color
    from collections import Counter
    pts={}
    for r in range(h):
        for c in range(w):
            if i[r][c]!=bg: pts.setdefault(i[r][c],[]).append((r,c))
    stroke=None; band=None
    for v,p in pts.items():
        rs=[r for r,c in p]; cs=[c for r,c in p]
        if len(p)>=3 and (max(rs)-min(rs)+max(cs)-min(cs))==len(p)-1: stroke=(v,p)
        else: band=(v,set(p))
    v,S=stroke
    (br,bp)=band
    def dist(b,c):
        # min Manhattan distance from point to band cells
        return min(abs(r-br_)+abs(c-bc_) for br_,bc_ in bp)
    ends=[min(S,key=dist(b,_)), max(S,key=dist(b,_))]
    e=min(ends,key=lambda p:dist(b,p))
    # stroke direction
    others=[p for p in S if p!=e]
    dr=others[0][0]-e[0]; dc=others[0][1]-e[1]
    import math
    L=math.gcd(abs(dr),abs(dc)); dr//=L; dc//=L
    # perpendicular directions
    perps=[(dc,-dr),(-dc,dr)]
    best=None
    for pr,pc in perps:
        path=[]; r,c=e[0]+pr,e[1]+pc
        while 0<=r<h and 0<=c<w and i[r][c]==bg:
            path.append((r,c)); r+=pr; c+=pc
        # must not immediately hit band; pick longer path that stays away
        if path and i[path[0][0]][path[0][1]]==bg and all(i[r][c]==bg for r,c in path) and (best is None or len(path)>len(best)):
            best=path
    o=[row[:] for row in i]
    for r,c in best: o[r][c]=3
    return o
